def is_Sub_Array(l1, l2): 
    if (len(l1) == 0): 
        return True
    if (len(l1) > len(l2)): 
        return False
    for i in range(len(l2) - len(l1) + 1): 
        if l2[i] == l1[0]: 
            j = 1
            while (j < len(l1)): 
                if (l2[i + j] != l1[j]): 
                    break
                j += 1
            if (j == len(l1)): 
                return True
    return False
